ttr[commandIndex], TPMA_CC, commandIndex))
		{
		  case TPM_CC_NV_Read:
		  case TPM_CC_PolicyNV:
		  case TPM_CC_NV_Certify:
		    // NV read lock counts as a read operation for authorization purposes.
